#!/usr/bin/env python3
from __future__ import annotations

import pathlib
import sys

POLICY_SOURCE = 'from __future__ import annotations\n\nimport hashlib\nimport re\nfrom dataclasses import dataclass\nfrom typing import Iterable\n\nBRIDGE_ACTIONS = frozenset({\n    "observe", "wait", "tap_node", "tap", "long_press", "swipe",\n    "scroll_node", "scroll_global", "set_text", "ime_action",\n    "back", "home", "recents", "open_app",\n    "tap_text", "set_text_best", "ime_best", "scroll_best", "run_ui_sequence",\n})\nREAD_ONLY = frozenset({"observe", "wait", "finish"})\nSTATE_CHANGING = frozenset({\n    "tap_node", "tap", "long_press", "swipe", "scroll_node", "scroll_global",\n    "set_text", "ime_action", "back", "home", "recents", "open_app",\n    "tap_text", "set_text_best", "ime_best", "scroll_best", "run_ui_sequence",\n})\n\n_EXTERNAL = re.compile(\n    r"\\b(send|kirim|post|publish|bagikan|share|call|panggil|telepon|submit|"\n    r"unggah|upload|reply|balas|allow|izinkan|grant|approve|setuju)\\b",\n    re.I,\n)\n_DESTRUCTIVE = re.compile(\n    r"\\b(delete|hapus|remove|uninstall|reset|factory|format|clear data|"\n    r"logout|keluar akun|pay|bayar|purchase|buy|beli|transfer|subscribe|"\n    r"berlangganan|wipe|erase)\\b",\n    re.I,\n)\n_AMBIGUOUS_CONFIRM = re.compile(\n    r"^(ok|yes|ya|confirm|konfirmasi|continue|lanjut|accept|terima|agree|"\n    r"setuju|allow|izinkan|done|selesai)$",\n    re.I,\n)\n_SEARCH = re.compile(r"\\b(search|cari|find|query|telusur|pencarian)\\b", re.I)\n_SENSITIVE = re.compile(\n    r"\\b(password|passwd|passcode|kata sandi|pin|otp|one.?time|verification.?code|"\n    r"kode verifikasi|security.?code|api.?key|access.?token|refresh.?token|"\n    r"secret|cvv|cvc|credit.?card|kartu kredit|private.?key|seed phrase|recovery phrase)\\b",\n    re.I,\n)\n_SECRET_VALUE = re.compile(\n    r"(?:bearer\\s+[A-Za-z0-9._~+/=-]{12,}|"\n    r"(?:sk|pk|api)[-_][A-Za-z0-9._-]{12,}|"\n    r"[A-Fa-f0-9]{32,}|"\n    r"[A-Za-z0-9+/]{40,}={0,2})"\n)\n\n\n@dataclass(frozen=True)\nclass GoalLock:\n    digest: str\n    allowed_packages: frozenset[str]\n    installed_packages: frozenset[str]\n    semantic_types: frozenset[str]\n    external_allowed: bool\n\n\ndef _norm(value: object) -> str:\n    return " ".join(str(value or "").casefold().split())\n\n\ndef build_goal_lock(goal: str, apps: list[dict], semantic_steps: list[dict] | None) -> GoalLock:\n    installed: set[str] = set()\n    labels: list[tuple[str, str]] = []\n    for app in apps or []:\n        if not isinstance(app, dict):\n            continue\n        package = str(app.get("package") or "").strip()\n        if not package:\n            continue\n        installed.add(package)\n        label = _norm(app.get("label"))\n        if label:\n            labels.append((label, package))\n\n    allowed: set[str] = set()\n    semantic_types: set[str] = set()\n    external_allowed = False\n    for step in semantic_steps or []:\n        if not isinstance(step, dict):\n            continue\n        typ = str(step.get("type") or "").strip().lower()\n        if typ:\n            semantic_types.add(typ)\n        package = str(step.get("package") or "").strip()\n        if typ == "open_app" and package and (not installed or package in installed):\n            allowed.add(package)\n        if typ in {"send", "call", "share", "post", "submit", "upload"}:\n            external_allowed = True\n\n    normalized_goal = _norm(goal)\n    if not allowed and normalized_goal:\n        for label, package in sorted(labels, key=lambda item: len(item[0]), reverse=True):\n            if len(label) >= 3 and label in normalized_goal:\n                allowed.add(package)\n                break\n\n    lexical_external = bool(_EXTERNAL.search(str(goal or "")))\n    if semantic_steps:\n        external_allowed = external_allowed and lexical_external\n    else:\n        external_allowed = lexical_external\n\n    digest = hashlib.sha256(str(goal or "").encode("utf-8", errors="replace")).hexdigest()[:20]\n    return GoalLock(\n        digest=digest,\n        allowed_packages=frozenset(allowed),\n        installed_packages=frozenset(installed),\n        semantic_types=frozenset(semantic_types),\n        external_allowed=external_allowed,\n    )\n\n\ndef _labels(screen: dict, action: dict) -> str:\n    pieces: list[str] = []\n    for key in ("target_label", "label", "summary"):\n        value = action.get(key)\n        if value:\n            pieces.append(str(value))\n    target = action.get("target")\n    if isinstance(target, dict):\n        for key in ("text", "desc", "view_id", "class"):\n            if target.get(key):\n                pieces.append(str(target.get(key)))\n    try:\n        node_id = int(action.get("node"))\n    except Exception:\n        node_id = None\n    if node_id is not None:\n        for node in screen.get("nodes") or []:\n            if not isinstance(node, dict):\n                continue\n            try:\n                current_id = int(node.get("id"))\n            except Exception:\n                continue\n            if current_id != node_id:\n                continue\n            for key in ("text", "desc", "view_id", "class"):\n                if node.get(key):\n                    pieces.append(str(node.get(key)))\n            break\n    return " ".join(pieces).strip()\n\n\ndef _ime_is_search(screen: dict, action: dict) -> bool:\n    role = str(action.get("role") or "").strip().lower()\n    if role == "search":\n        return True\n    return bool(_SEARCH.search(_labels(screen, action)))\n\n\ndef classify_action(screen: dict, action: dict, lock: GoalLock) -> tuple[str, str]:\n    typ = str(action.get("type") or "").strip()\n    if typ in READ_ONLY:\n        return "safe", "tanpa perubahan perangkat"\n    if typ not in BRIDGE_ACTIONS:\n        return "blocked", "capability tidak terdaftar pada Action Firewall"\n\n    if typ == "open_app":\n        package = str(action.get("package") or "").strip()\n        if not package:\n            return "blocked", "package tujuan kosong"\n        if lock.installed_packages and package not in lock.installed_packages:\n            return "blocked", "package tujuan tidak berasal dari inventori aplikasi"\n        if lock.allowed_packages and package not in lock.allowed_packages:\n            return "blocked", "package berada di luar Goal Lock"\n\n    current_package = str(screen.get("package") or "").strip()\n    if lock.allowed_packages and current_package and current_package not in lock.allowed_packages:\n        if current_package in lock.installed_packages and typ not in {"open_app", "back", "home", "recents"}:\n            return "blocked", "aksi pada aplikasi lain berada di luar Goal Lock"\n        if typ in {"tap_node", "tap", "long_press", "tap_text", "set_text", "set_text_best", "ime_action", "ime_best"}:\n            return "uncertain", "transisi system UI membutuhkan persetujuan spesifik"\n\n    label = _labels(screen, action)\n    if _DESTRUCTIVE.search(label):\n        return "blocked", (label[:180] or "aksi destruktif diblokir")\n\n    if bool(action.get("_external")):\n        if not lock.external_allowed:\n            return "blocked", "efek eksternal tidak diminta pengguna"\n        return "external", "efek eksternal eksplisit"\n\n    if typ in {"ime_action", "ime_best"}:\n        if _ime_is_search(screen, action):\n            return "write", "submit pencarian yang terikat Goal Lock"\n        if lock.external_allowed:\n            return "external", "IME dapat mengirim atau men-submit data"\n        return "uncertain", "efek IME tidak dapat dibuktikan hanya lokal"\n\n    if typ in {"set_text", "set_text_best"}:\n        return "write", "mengubah isi field"\n\n    if _EXTERNAL.search(label):\n        if lock.external_allowed:\n            return "external", (label[:180] or "kontrol eksternal")\n        return "blocked", "kontrol eksternal berada di luar Goal Lock"\n\n    if _AMBIGUOUS_CONFIRM.match(" ".join(label.split())):\n        return "uncertain", "kontrol konfirmasi ambigu membutuhkan persetujuan spesifik"\n\n    if typ == "tap" and not label:\n        return "uncertain", "tap koordinat tidak memiliki identitas target"\n\n    if typ in {"tap_node", "tap", "long_press", "tap_text"}:\n        return "navigate", (label[:180] or "kontrol UI")\n    if typ in {"swipe", "scroll_node", "scroll_global", "scroll_best", "back", "home", "recents", "open_app"}:\n        return "navigate", "navigasi layar"\n    if typ == "run_ui_sequence":\n        return "navigate", "urutan UI terkompilasi"\n    return "blocked", "aksi tidak dikenali"\n\n\ndef validate_sequence(steps: Iterable[dict], lock: GoalLock) -> tuple[bool, str]:\n    for index, step in enumerate(steps or []):\n        if not isinstance(step, dict):\n            return False, f"step {index + 1} bukan object"\n        typ = str(step.get("type") or "").strip()\n        if typ not in BRIDGE_ACTIONS - {"run_ui_sequence"}:\n            return False, f"step {index + 1} capability tidak terdaftar"\n        if typ == "open_app":\n            package = str(step.get("package") or "").strip()\n            if not package:\n                return False, f"step {index + 1} package kosong"\n            if lock.installed_packages and package not in lock.installed_packages:\n                return False, f"step {index + 1} package tidak dikenal"\n            if lock.allowed_packages and package not in lock.allowed_packages:\n                return False, f"step {index + 1} package di luar Goal Lock"\n        if bool(step.get("_external")) and not lock.external_allowed:\n            return False, f"step {index + 1} efek eksternal tidak diminta"\n        label = " ".join(str(step.get(k) or "") for k in ("target", "target_label", "label"))\n        if _DESTRUCTIVE.search(label):\n            return False, f"step {index + 1} destruktif"\n    return True, "sequence sesuai Goal Lock"\n\n\ndef _selector_matches(selector: dict, node: dict) -> bool:\n    stable = []\n    for key in ("view_id", "text", "desc", "class", "path", "bounds"):\n        value = selector.get(key)\n        if value not in (None, "", False):\n            stable.append((key, value))\n    if not stable:\n        return False\n    matched_strong = False\n    for key, value in stable:\n        node_value = node.get(key)\n        if node_value in (None, ""):\n            if key in {"view_id", "path"}:\n                return False\n            continue\n        if node_value != value:\n            return False\n        if key in {"view_id", "path", "bounds", "text", "desc"}:\n            matched_strong = True\n    return matched_strong\n\n\ndef validate_fresh_target(origin: dict | None, fresh: dict, action: dict) -> tuple[bool, str]:\n    typ = str(action.get("type") or "").strip()\n    if typ not in STATE_CHANGING:\n        return True, "read-only"\n    if isinstance(origin, dict):\n        before_package = str(origin.get("package") or "")\n        fresh_package = str(fresh.get("package") or "")\n        if before_package and fresh_package and before_package != fresh_package and typ != "open_app":\n            return False, "window/package berubah sebelum aksi"\n\n    target = action.get("target")\n    if isinstance(target, dict):\n        for node in fresh.get("nodes") or []:\n            if isinstance(node, dict) and _selector_matches(target, node):\n                return True, "selector ditemukan ulang pada state terbaru"\n        return False, "selector tidak lagi cocok dengan state terbaru"\n\n    if action.get("node") is not None and typ in {"tap_node", "set_text", "ime_action", "long_press", "scroll_node"}:\n        return False, "node id tanpa selector stabil ditolak"\n    return True, "aksi tidak bergantung node lama"\n\n\ndef package_scope_allows(fresh: dict, action: dict, lock: GoalLock) -> tuple[bool, str]:\n    typ = str(action.get("type") or "").strip()\n    package = str(fresh.get("package") or "").strip()\n    if not lock.allowed_packages or not package:\n        return True, "scope tidak mengikat package saat ini"\n    if package in lock.allowed_packages:\n        return True, "package berada dalam Goal Lock"\n    if package in lock.installed_packages and typ not in {"open_app", "back", "home", "recents"}:\n        return False, "state berpindah ke aplikasi lain"\n    return True, "system transition tidak dieksekusi sebagai perluasan aplikasi"\n\n\ndef _redact_value(value: object, *, sensitive_context: bool) -> object:\n    if not isinstance(value, str) or not value:\n        return value\n    out = _SECRET_VALUE.sub("[REDACTED_SECRET]", value)\n    if sensitive_context and out.strip():\n        return "[REDACTED_SENSITIVE]"\n    return out\n\n\ndef redact_compact_screen(compact: dict) -> dict:\n    out = dict(compact or {})\n    nodes = []\n    for raw in out.get("nodes") or []:\n        if not isinstance(raw, dict):\n            continue\n        node = dict(raw)\n        context = " ".join(\n            str(node.get(k) or "")\n            for k in ("text", "view_id", "desc", "class", "hint", "content_description")\n        )\n        sensitive_context = bool(node.get("password") or node.get("is_password") or _SENSITIVE.search(context))\n        for key in ("text", "desc", "hint"):\n            if key in node:\n                node[key] = _redact_value(node.get(key), sensitive_context=sensitive_context)\n        nodes.append(node)\n    out["nodes"] = nodes\n    if isinstance(out.get("vision_summary"), str):\n        out["vision_summary"] = _SECRET_VALUE.sub("[REDACTED_SECRET]", out["vision_summary"])\n    return out\n\n\ndef is_sensitive_screen(screen: dict) -> bool:\n    for node in screen.get("nodes") or []:\n        if not isinstance(node, dict):\n            continue\n        if bool(node.get("password") or node.get("is_password")):\n            return True\n        context = " ".join(\n            str(node.get(k) or "")\n            for k in ("text", "desc", "view_id", "class", "hint", "content_description")\n        )\n        if _SENSITIVE.search(context):\n            return True\n    title = str(screen.get("window_title") or "")\n    return bool(_SENSITIVE.search(title))\n'
SHIM_SOURCE = '# RC32_POLICY_BOUNDARY\nfrom .policy import (\n    BRIDGE_ACTIONS as _RC32_BRIDGE_ACTIONS,\n    STATE_CHANGING as _RC32_STATE_CHANGING,\n    build_goal_lock as _rc32_build_goal_lock,\n    classify_action as _rc32_classify_action,\n    is_sensitive_screen as _rc32_is_sensitive_screen,\n    package_scope_allows as _rc32_package_scope_allows,\n    redact_compact_screen as _rc32_redact_compact_screen,\n    validate_fresh_target as _rc32_validate_fresh_target,\n    validate_sequence as _rc32_validate_sequence,\n)\n\n_RC31_RUN = AndroidAgent.run\n_RC31_RISK = AndroidAgent.risk\n_RC31_COMPACT_SCREEN = AndroidAgent._compact_screen\n_RC31_WITH_VISION = AndroidAgent._with_vision\n_RC31_ENRICH_ACTION = AndroidAgent._enrich_action\n\n_RC32_RISK_ORDER = {\n    "safe": 0,\n    "read": 0,\n    "navigate": 1,\n    "write": 2,\n    "uncertain": 3,\n    "external": 4,\n    "blocked": 5,\n}\n\n\ndef _rc32_current_lock(agent):\n    lock = getattr(agent, "_rc32_goal_lock", None)\n    if lock is not None:\n        return lock\n    return _rc32_build_goal_lock("", [], [])\n\n\ndef _rc32_risk(self, screen: dict, action: dict) -> tuple[str, str]:\n    lock = _rc32_current_lock(self)\n    policy_risk, policy_detail = _rc32_classify_action(screen or {}, action or {}, lock)\n    if policy_risk == "blocked":\n        return policy_risk, policy_detail\n    try:\n        legacy_risk, legacy_detail = _RC31_RISK(self, screen, action)\n    except Exception:\n        legacy_risk, legacy_detail = "uncertain", "legacy risk unavailable"\n    if _RC32_RISK_ORDER.get(legacy_risk, 3) > _RC32_RISK_ORDER.get(policy_risk, 3):\n        return legacy_risk, legacy_detail\n    return policy_risk, policy_detail\n\n\ndef _rc32_compact_screen(screen: dict, hints: str = "") -> dict:\n    compact = _RC31_COMPACT_SCREEN(screen, hints)\n    return _rc32_redact_compact_screen(compact)\n\n\ndef _rc32_with_vision(self, goal: str, screen: dict) -> dict:\n    if _rc32_is_sensitive_screen(screen or {}):\n        try:\n            self.store.log_event(\n                "agent_privacy_vision_blocked",\n                {"package": str((screen or {}).get("package") or "")[:180]},\n            )\n        except Exception:\n            pass\n        return screen\n    return _RC31_WITH_VISION(self, goal, screen)\n\n\ndef _rc32_enrich_action(self, screen: dict, action: dict) -> dict:\n    self._rc32_origin_screen = screen\n    payload = _RC31_ENRICH_ACTION(self, screen, action)\n    if isinstance(payload, dict):\n        payload = dict(payload)\n        payload["_goal_lock"] = getattr(_rc32_current_lock(self), "digest", "")\n    return payload\n\n\nclass _RC32ToolProxy:\n    def __init__(self, agent, inner):\n        self._agent = agent\n        self._inner = inner\n\n    def __getattr__(self, name):\n        return getattr(self._inner, name)\n\n    def _blocked(self, error: str, detail: str):\n        try:\n            self._agent.store.log_event(\n                "agent_action_firewall",\n                {"ok": False, "error": error[:80], "detail": detail[:260]},\n            )\n        except Exception:\n            pass\n        return {\n            "ok": False,\n            "error": error,\n            "detail": detail[:300],\n            "policy_blocked": True,\n            "execution_mode": "blocked",\n        }\n\n    @staticmethod\n    def _clean(action: dict) -> dict:\n        return {\n            key: value\n            for key, value in action.items()\n            if key not in {"_goal_lock"}\n        }\n\n    def execute(self, action: dict):\n        if not isinstance(action, dict):\n            return self._blocked("invalid_action", "action bukan object")\n        typ = str(action.get("type") or "").strip()\n        lock = _rc32_current_lock(self._agent)\n\n        if typ == "run_ui_sequence":\n            steps = action.get("steps") or []\n            ok, detail = _rc32_validate_sequence(steps, lock)\n            if not ok:\n                return self._blocked("sequence_outside_goal_lock", detail)\n            return self._inner.execute(self._clean(action))\n\n        if typ not in _RC32_BRIDGE_ACTIONS:\n            # Registered direct integrations remain available to other callers,\n            # but the generic Android planner may not widen its own capabilities.\n            return self._blocked("unknown_agent_capability", typ or "empty")\n\n        if typ in _RC32_STATE_CHANGING:\n            try:\n                fresh = self._agent.bridge.screen()\n            except Exception as exc:\n                return self._blocked("fresh_state_unavailable", str(exc))\n\n            ok, detail = _rc32_package_scope_allows(fresh, action, lock)\n            if not ok:\n                return self._blocked("package_scope_changed", detail)\n\n            origin = getattr(self._agent, "_rc32_origin_screen", None)\n            ok, detail = _rc32_validate_fresh_target(origin, fresh, action)\n            if not ok:\n                return self._blocked("stale_target", detail)\n\n        return self._inner.execute(self._clean(action))\n\n\ndef _rc32_run(self, goal: str, approve, *, task_authorized: bool = False, semantic_steps: list[dict] | None = None) -> str:\n    try:\n        apps = self._apps()\n    except Exception:\n        apps = []\n    lock = _rc32_build_goal_lock(goal, apps, semantic_steps or [])\n    self._rc32_goal_lock = lock\n    try:\n        self.store.log_event(\n            "agent_goal_lock",\n            {\n                "digest": lock.digest,\n                "packages": sorted(lock.allowed_packages),\n                "semantic_types": sorted(lock.semantic_types),\n                "external_allowed": lock.external_allowed,\n            },\n        )\n    except Exception:\n        pass\n\n    original_tools = getattr(self, "tools", None)\n    if original_tools is not None and not isinstance(original_tools, _RC32ToolProxy):\n        self.tools = _RC32ToolProxy(self, original_tools)\n    try:\n        return _RC31_RUN(\n            self,\n            goal,\n            approve,\n            task_authorized=task_authorized,\n            semantic_steps=semantic_steps,\n        )\n    finally:\n        if original_tools is not None:\n            self.tools = original_tools\n        for name in ("_rc32_goal_lock", "_rc32_origin_screen"):\n            try:\n                delattr(self, name)\n            except Exception:\n                pass\n\n\nAndroidAgent.risk = _rc32_risk\nAndroidAgent._compact_screen = staticmethod(_rc32_compact_screen)\nAndroidAgent._with_vision = _rc32_with_vision\nAndroidAgent._enrich_action = _rc32_enrich_action\nAndroidAgent.run = _rc32_run\n'
OLD_HANDLER = '    def _handler_for(self, action_type: str) -> ToolSpec:\n        spec = self._handlers.get(action_type)\n        if spec is not None:\n            return spec\n        return ToolSpec(\n            "android_bridge",\n            self.bridge.action,\n            "Universal Android Accessibility/gesture transport",\n            "navigate",\n            "local",\n            False,\n            "android_state",\n        )\n'
NEW_HANDLER = '    def _handler_for(self, action_type: str) -> ToolSpec:\n        spec = self._handlers.get(action_type)\n        if spec is not None:\n            return spec\n        # RC32_BRIDGE_FALLBACK: unknown capabilities must be explicitly\n        # registered instead of silently inheriting AndroidBridge privileges.\n        bridge_actions = {\n            "observe", "wait", "tap_node", "tap", "long_press", "swipe",\n            "scroll_node", "scroll_global", "set_text", "ime_action",\n            "back", "home", "recents", "open_app",\n            "tap_text", "set_text_best", "ime_best", "scroll_best",\n            "run_ui_sequence",\n        }\n        if action_type not in bridge_actions:\n            raise ValueError(f"capability tidak terdaftar: {action_type}")\n        return ToolSpec(\n            "android_bridge",\n            self.bridge.action,\n            "Universal Android Accessibility/gesture transport",\n            "navigate",\n            "local",\n            False,\n            "android_state",\n        )\n'


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("usage: apply-policy-boundary-core-rc32.py <termux-root>")
    root = pathlib.Path(sys.argv[1]).resolve()
    core = root / "core/furina_agent"
    agent = core / "agent.py"
    runtime = core / "tool_runtime.py"
    version = core / "version.py"
    policy_path = core / "policy.py"
    for path in (agent, runtime, version):
        if not path.is_file():
            raise SystemExit(f"missing RC32 source: {path}")

    current_version = version.read_text(encoding="utf-8")
    if 'VERSION = "1.0.0-rc32"' in current_version and "RC32_POLICY_BOUNDARY" in agent.read_text(encoding="utf-8"):
        print("Furina Core RC32 policy boundary already applied")
        return
    if 'VERSION = "1.0.0-rc31"' not in current_version:
        raise SystemExit("RC32 requires Core RC31")

    policy_path.write_text(POLICY_SOURCE, encoding="utf-8")

    a = agent.read_text(encoding="utf-8")
    if "RC32_POLICY_BOUNDARY" not in a:
        a = a.rstrip() + "\n\n" + SHIM_SOURCE
    agent.write_text(a, encoding="utf-8")

    t = runtime.read_text(encoding="utf-8")
    if "RC32_BRIDGE_FALLBACK" not in t:
        if t.count(OLD_HANDLER) != 1:
            raise SystemExit(f"RC32 handler marker mismatch: {t.count(OLD_HANDLER)}")
        t = t.replace(OLD_HANDLER, NEW_HANDLER, 1)
    runtime.write_text(t, encoding="utf-8")

    v = current_version.replace('VERSION = "1.0.0-rc31"', 'VERSION = "1.0.0-rc32"', 1)
    version.write_text(v, encoding="utf-8")

    for path in (policy_path, agent, runtime, version):
        compile(path.read_text(encoding="utf-8"), str(path), "exec")

    final = agent.read_text(encoding="utf-8")
    required = (
        "RC32_POLICY_BOUNDARY",
        "agent_goal_lock",
        "agent_action_firewall",
        "agent_privacy_vision_blocked",
        "stale_target",
        "_rc32_validate_fresh_target",
        "_rc32_redact_compact_screen",
    )
    missing = [item for item in required if item not in final]
    if missing:
        raise SystemExit("RC32 Agent boundary incomplete: " + ", ".join(missing))

    p = policy_path.read_text(encoding="utf-8")
    for marker in ("class GoalLock", "def classify_action", "def validate_fresh_target", "def redact_compact_screen"):
        if marker not in p:
            raise SystemExit("RC32 policy module incomplete: " + marker)
    if "RC32_BRIDGE_FALLBACK" not in runtime.read_text(encoding="utf-8"):
        raise SystemExit("RC32 runtime fail-closed boundary missing")
    if 'VERSION = "1.0.0-rc32"' not in version.read_text(encoding="utf-8"):
        raise SystemExit("RC32 Core version missing")
    print("Furina Core RC32 Goal Lock + Action Firewall + fresh-state/privacy boundary: OK")


if __name__ == "__main__":
    main()
